#include <bits/stdc++.h>
using namespace std;

long long max_piece_length(const vector<long long>& a, long long k) {
    long long sum = accumulate(a.begin(), a.end(), 0LL);
    if (sum < k) return 0;
    long long lo = 1, hi = *max_element(a.begin(), a.end()) + 1;
    while (lo + 1 < hi) {
        long long mid = lo + (hi - lo) / 2;
        long long cnt = 0;
        for (long long x : a) cnt += x / mid;
        if (cnt >= k) lo = mid;
        else hi = mid;
    }
    return lo;
}

